static int vfGlyph(const VecFont &f, char ch) {
  if (!f.chars) return ch >= '0' && ch <= '9' ? ch - '0' : ch == ':' ? 10 : -1;
  for (int i = 0;; i++) {  // fonte de texto: posição na lista de caracteres
    char c = pgm_read_byte(&f.chars[i]);
    if (!c) return -1;
    if (c == ch) return i;
  }
}
static int vfAdv(const VecFont &f, char ch, int h) {
  int g = vfGlyph(f, ch);
  return (g >= 0 ? pgm_read_word(&f.adv[g]) : pgm_read_word(&f.adv[0]) / 2) * h / 720;
}

int vecWidth(const VecFont &f, const char *s, int h) {
  int w = 0;
  for (; *s; s++) w += vfAdv(f, *s, h);
  return w;
}

static void vfSpan(uint8_t *cov, int n, int a, int b) {
  if (a < 0) a = 0;
  if (b > n * 16) b = n * 16;
  if (b <= a) return;
  int ia = a >> 4, ib = b >> 4;
  if (ia == ib) {
    cov[ia] += b - a;
    return;
  }
  cov[ia] += 16 - (a & 15);
  for (int i = ia + 1; i < ib; i++) cov[i] += 16;
  if (ib < n) cov[ib] += b & 15;
}

void vecText(const VecFont &f, int x, int y, int h, const char *s, uint16_t fg, uint16_t bg) {
  int W = vecWidth(f, s, h);
  if (W > 240) W = 240;
  if (W <= 0 || h <= 0) return;
  // buffers só durante o desenho (RAM fixa é escassa: o GIF do álbum precisa de ~24 KB contíguos)
  uint8_t *cov = (uint8_t *)malloc(W * 3 + 2);  // cobertura (W) + linha RGB565 alinhada (2W)
  if (!cov) return;
  uint16_t *row = (uint16_t *)(cov + ((W + 1) & ~1));
  uint16_t pal[17];
  for (int i = 0; i <= 16; i++) pal[i] = mix16(bg, fg, i);
  for (int r = 0; r < h; r++) {
    memset(cov, 0, W);
    int ox = 0;
    for (const char *p = s; *p; ox += vfAdv(f, *p, h), p++) {
      int g = vfGlyph(f, *p);
      if (g < 0) continue;
      int c0 = pgm_read_byte(&f.glyph[g]), c1 = pgm_read_byte(&f.glyph[g + 1]);
      for (int j = 0; j < 4; j++) {
        int sy = (int)((r + (j + 0.5f) / 4) * 720 / h);
        int xs[32], n = 0;  // x em 1/16 de unidade, *2 + sentido (1 = descendo)
        for (int c = c0; c < c1; c++) {
          int s0 = c ? pgm_read_word(&f.cend[c - 1]) : 0, e = pgm_read_word(&f.cend[c]);
          for (int i = s0; i < e; i++) {
            int k = i + 1 < e ? i + 1 : s0;
            int ay = (int16_t)pgm_read_word(&f.pt[i][1]), by = (int16_t)pgm_read_word(&f.pt[k][1]);
            if ((ay <= sy && sy < by) || (by <= sy && sy < ay)) {
              int ax = (int16_t)pgm_read_word(&f.pt[i][0]), bx = (int16_t)pgm_read_word(&f.pt[k][0]);
              if (n < 32) xs[n++] = (ax * 16 + (sy - ay) * (bx - ax) * 16 / (by - ay)) * 2 + (ay < by);
            }
          }
        }
        for (int i = 1; i < n; i++)
          for (int k = i; k > 0 && xs[k] < xs[k - 1]; k--) {
            int t = xs[k];
            xs[k] = xs[k - 1];
            xs[k - 1] = t;
          }
        int wn = 0;
        for (int k = 0; k + 1 < n; k++) {
          wn += (xs[k] & 1) ? 1 : -1;
          if (wn) vfSpan(cov, W, ox * 16 + (xs[k] >> 1) * h / 720, ox * 16 + (xs[k + 1] >> 1) * h / 720);
        }
      }
    }
    for (int i = 0; i < W; i++) row[i] = pal[(cov[i] > 64 ? 64 : cov[i]) / 4];
    blit(x, y + r, row, W, 1);
  }
  free(cov);
}
